for (const { weight, value } of items) {
  for (let w = weight; w <= capacity; w++) {
    dp[w] = Math.max(dp[w], dp[w - weight] + value)
  }
}

function paths(r: number, c: number, memo = new Map<string, number>()): number {
  if (r === 0 || c === 0) return 1
  const key = r + ':' + c
  if (memo.has(key)) return memo.get(key)!
  const v = paths(r - 1, c, memo) + paths(r, c - 1, memo)
  memo.set(key, v)
  return v
}
